class OpenAIFunctionCalling:
    def __init__(self, config):
        self.config = config
        self.functions = self.setup_functions()

    def call_gpt_retry(self, device, max_retries=4, include_functions=False):
        wait_time = 0.5
        for attempt in range(max_retries):
            try:
                if(include_functions):
                    response = openai.ChatCompletion.create(
                        model=self.config['llm']['gpt_model'],
                        messages=device.messages,
                        functions=self.functions,
                        max_tokens=300,
                    )
                else:
                    response = openai.ChatCompletion.create(
                        model=self.config['llm']['gpt_model'],
                        messages=device.messages,
                        max_tokens=150,
                    )
                return (True, response)
            except Exception as e:
                device.log.error(f"Attempt {attempt+1} of {max_retries} failed: {e}")
                if attempt < max_retries - 1:
                    time.sleep(wait_time)
                    wait_time *= 2  # backoff
                else:
                    return (False, e)

        "options": {
            "num_predict": -2,
            "temperature": 1.0
        }
    }
    response = requests.post(f'{OLLAMA_BASE_URL}/v1/chat/completions', headers=headers, json=payload, stream=True, timeout=30)
    response.raise_for_status()

    full_response = ""
    line_buffer = ""
    for line in response.iter_lines(decode_unicode=True):
        if line.startswith("data:"):
            line = line[5:].strip()  # Remove the "data:" prefix
        if line:
            try:
                chunk = json.loads(line)
                delta_content = chunk['choices'][0]['delta'].get('content', '')
                if delta_content:
                    line_buffer += delta_content
                    if '\n' in line_buffer:
                        lines = line_buffer.split('\n')
                        for line in lines[:-1]:
                            if not is_xai_tts_enabled():
                                print(NEON_GREEN + line + RESET_COLOR)
                            full_response += line + '\n'
                        line_buffer = lines[-1]
            except json.JSONDecodeError:
                continue
    if line_buffer:
        if not is_xai_tts_enabled():
            print(NEON_GREEN + line_buffer + RESET_COLOR)
        full_response += line_buffer
    return full_response

